// Fictional knowledge base: Nordlight Home (online home & garden store, Lithuania)
const articles = [
  { title: 'Returns', text: 'Any item can be returned within 30 days of delivery if unused and in original packaging. Used power tools can only be returned if faulty (see Warranty). Start a return in My Account > Orders > Return item. Faulty items get a free return label; change-of-mind returns cost EUR 3.99 shipping. Refunds go to the original payment method within 14 days of us receiving the item.' },
  { title: 'Delivery', text: 'Standard delivery in Lithuania takes 2-4 working days and costs EUR 3.99, free over EUR 50. Latvia and Estonia: 3-6 working days, EUR 6.99. Large items (furniture, sheds, appliances) come by courier in a 2-hour slot for EUR 29. A tracking link is emailed when the order ships. If tracking shows no movement for 5 working days, we investigate with the courier and resend or refund.' },
  { title: 'Warranty', text: 'All products have a 2-year legal guarantee. Power tools registered on the manufacturer website get up to 3 years. For a warranty claim, send the order number and a photo or video of the fault. We repair, replace or refund within 30 days. Misuse and normal wear are not covered.' },
  { title: 'Order changes and cancellations', text: 'Orders can be changed or cancelled free of charge until their status is Shipped, usually within 24 hours. After shipping an order cannot be cancelled; use the returns process instead.' },
  { title: 'Payments and invoices', text: 'We accept cards, bank links and pay-later. Companies can request a VAT invoice with company code and VAT code at checkout or within 7 days. If a payment was taken twice, the duplicate is refunded automatically within 5 working days; if not, support refunds it manually.' },
  { title: 'Privacy and data requests', text: 'Requests to access, correct or delete personal data (GDPR requests) are handled only by the Data Protection Officer within 30 days. Support agents must not process them; they forward them to the DPO and confirm receipt to the customer.' }
];
return articles.map(a => ({ json: a }));
